// ---------- Data Structures ----------

type Agent struct {
	ID        string    `json:"id"`
	LastSeen  time.Time `json:"last_seen"`
	Pending   []string  `json:"pending_commands"`
	Completed []string  `json:"completed_commands"`
}

type CommandRequest struct {
	AgentID string `json:"agent_id"`
}

type CommandResponse struct {
	Command string `json:"command"`
}

type ResultRequest struct {
	AgentID string `json:"agent_id"`
	Output  string `json:"output"`
}

// ---------- Server State ----------

var (
	mu       sync.Mutex
	agents   = make(map[string]*Agent)
	token    = "supersecret-token-12345"
	adminCmd = make(chan string, 10)
)

// ---------- Helper Functions ----------

func authCheck(r *http.Request) bool {
	return r.Header.Get("X-Auth-Token") == token
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func getOrCreateAgent(id string) *Agent {
	mu.Lock()
	defer mu.Unlock()
	if a, ok := agents[id]; ok {
		return a
	}
	a := &Agent{ID: id, LastSeen: time.Now()}
	agents[id] = a
	return a
}

// ---------- HTTP Handlers ----------

func registerHandler(w http.ResponseWriter, r *http.Request) {
	if !authCheck(r) {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
		return
	}
	var req CommandRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid JSON"})
		return
	}
	a := getOrCreateAgent(req.AgentID)
	a.LastSeen = time.Now()
	writeJSON(w, http.StatusOK, map[string]string{"status": "registered", "agent_id": a.ID})
}

func commandHandler(w http.ResponseWriter, r *http.Request) {
	if !authCheck(r) {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
		return
	}
	var req CommandRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid JSON"})
		return
	}
	a := getOrCreateAgent(req.AgentID)
	a.LastSeen = time.Now()

	// Pop command from pending queue
	mu.Lock()
	var cmd string
	if len(a.Pending) > 0 {
		cmd = a.Pending[0]
		a.Pending = a.Pending[1:]
	}
	mu.Unlock()

	if cmd == "" {
		writeJSON(w, http.StatusOK, CommandResponse{Command: ""})
		return
	}
	writeJSON(w, http.StatusOK, CommandResponse{Command: cmd})
}

func resultHandler(w http.ResponseWriter, r *http.Request) {
	if !authCheck(r) {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
		return
	}
	var req ResultRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid JSON"})
		return
	}
	a := getOrCreateAgent(req.AgentID)
	a.LastSeen = time.Now()
	mu.Lock()
	a.Completed = append(a.Completed, fmt.Sprintf("%s -> %s", time.Now().Format(time.RFC3339), req.Output))
	mu.Unlock()
	log.Printf("[RESULT] Agent %s: %s", req.AgentID, req.Output)
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func listAgentsHandler(w http.ResponseWriter, r *http.Request) {
	if !authCheck(r) {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
		return
