	mu.Lock()
	defer mu.Unlock()
	type agentView struct {
		ID        string   `json:"id"`
		LastSeen  string   `json:"last_seen"`
		Pending   []string `json:"pending_commands"`
		Completed []string `json:"completed_commands"`
	}
	list := []agentView{}
	for _, a := range agents {
		list = append(list, agentView{
			ID:        a.ID,
			LastSeen:  a.LastSeen.Format(time.RFC3339),
			Pending:   a.Pending,
			Completed: a.Completed,
		})
	}
	writeJSON(w, http.StatusOK, map[string][]agentView{"agents": list})
