        require(balances[msg.sender] >= amount, "Insufficient balance");
        balances[msg.sender] -= amount;
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");
        emit Withdrawn(msg.sender, amount);
    }

    // Emergency pause - but NOT fund draining
    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}
```

This contract:
- Allows users to deposit and withdraw their own funds
- Can be paused in emergencies (but funds stay locked)
- Has transparent events for all activity
- Cannot be used to drain user funds

